    <style>
      .student-progress-page{padding-bottom:42px}.student-progress-shell{max-width:1120px;margin:0 auto;padding:28px 20px}.student-progress-header{display:flex;justify-content:space-between;align-items:flex-start;gap:22px;margin-bottom:22px}.student-progress-eyebrow{margin:0 0 7px;color:var(--primary);font-size:.74rem;font-weight:750;letter-spacing:.08em;text-transform:uppercase}.student-progress-header h1{margin:0;font-size:clamp(1.65rem,3vw,2.25rem);color:var(--text-primary)}.student-progress-header p{margin:7px 0 0;color:var(--text-muted)}.student-progress-filter{min-width:255px;display:grid;gap:7px}.student-progress-filter label{font-size:.76rem;font-weight:700;color:var(--text-muted)}.student-progress-primary{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);gap:14px;margin:0 0 18px}.student-progress-hero-card,.student-progress-journey,.student-progress-note{padding:18px;border:1px solid var(--border);border-radius:var(--radius-lg);background:var(--surface);box-shadow:var(--shadow-sm)}.student-progress-hero-card{display:grid;gap:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--secondary) 8%,var(--surface)),var(--surface))}.student-progress-hero-top{display:flex;justify-content:space-between;gap:16px;align-items:flex-start}.student-progress-hero-card h2,.student-progress-journey h2,.student-progress-note h2{margin:0;color:var(--text-primary);font-size:1.02rem}.student-progress-hero-percent{display:block;margin-top:7px;color:var(--text-primary);font-size:clamp(2.15rem,5vw,3.35rem);line-height:.95;font-weight:800}.student-progress-hero-status{display:inline-flex;align-items:center;padding:5px 10px;border-radius:999px;background:color-mix(in srgb,var(--primary) 14%,transparent);color:var(--primary);font-size:.78rem;font-weight:750;white-space:nowrap}.student-progress-hero-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.student-progress-hero-grid span{display:block;color:var(--text-muted);font-size:.74rem}.student-progress-hero-grid strong{display:block;margin-top:3px;color:var(--text-primary);font-size:1.02rem}.student-progress-journey{display:grid;gap:12px}.student-progress-journey-step{position:relative;padding-left:22px}.student-progress-journey-step:before{content:\"\";position:absolute;left:2px;top:4px;width:10px;height:10px;border-radius:50%;background:var(--secondary);box-shadow:0 0 0 4px color-mix(in srgb,var(--secondary) 12%,transparent)}.student-progress-journey-step:not(:last-child):after{content:\"\";position:absolute;left:6px;top:21px;bottom:-11px;width:1px;background:var(--border)}.student-progress-journey-step h3{margin:0;color:var(--text-primary);font-size:.94rem}.student-progress-journey-step p{margin:2px 0 8px;color:var(--text-muted);font-size:.78rem}.student-progress-journey-facts{display:flex;flex-wrap:wrap;gap:7px}.student-progress-journey-facts span{display:inline-flex;gap:4px;padding:4px 8px;border-radius:999px;background:var(--surface-hover);color:var(--text-secondary);font-size:.75rem}.student-progress-note{margin:0 0 18px;border-left:4px solid var(--primary);background:color-mix(in srgb,var(--primary) 7%,var(--surface))}.student-progress-note p{margin:8px 0 0;color:var(--text-secondary);line-height:1.55}.student-progress-overview{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:22px}.student-progress-metric{padding:15px 16px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface);box-shadow:var(--shadow-sm)}.student-progress-metric span{display:block;color:var(--text-muted);font-size:.77rem}.student-progress-metric strong{display:block;margin-top:6px;color:var(--text-primary);font-size:1.28rem}.student-progress-period{margin:0 0 20px;color:var(--text-muted);font-size:.86rem}.student-progress-section{padding:18px 20px;margin:0 0 12px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface);box-shadow:var(--shadow-sm)}.student-progress-section-header{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:12px}.student-progress-section-header h2{margin:0;color:var(--text-primary);font-size:1.08rem}.student-progress-section-date{color:var(--text-muted);font-size:.78rem;white-space:nowrap}.student-progress-row{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:10px 0;border-top:1px solid var(--border)}.student-progress-row:first-of-type{border-top:0}.student-progress-row-label{display:flex;align-items:center;gap:8px;color:var(--text-secondary);font-size:.9rem}.student-progress-status{display:inline-flex;align-items:center;gap:6px;padding:4px 9px;border-radius:999px;font-size:.78rem;font-weight:700;white-space:nowrap}.student-progress-status.is-success{background:color-mix(in srgb,var(--success) 14%,transparent);color:var(--success)}.student-progress-status.is-warning{background:color-mix(in srgb,var(--warning) 16%,transparent);color:var(--warning)}.student-progress-status.is-danger{background:color-mix(in srgb,var(--danger) 14%,transparent);color:var(--danger)}.student-progress-status.is-muted{background:var(--surface-hover);color:var(--text-muted)}.student-progress-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}.student-progress-action{display:inline-flex;align-items:center;min-height:34px;padding:6px 10px;border:1px solid var(--border);border-radius:var(--radius-sm);color:var(--secondary);font-size:.78rem;font-weight:700;text-decoration:none}.student-progress-action:hover,.student-progress-action:focus-visible{border-color:var(--secondary);color:var(--secondary);text-decoration:none}.student-progress-empty{padding:20px;border:1px dashed var(--border);border-radius:var(--radius-md);color:var(--text-muted);text-align:center}.student-progress-attention{margin-top:22px}.student-progress-attention h2{margin:0 0 10px;font-size:1.1rem;color:var(--text-primary)}.student-progress-attention-list{display:grid;gap:8px;margin:0;padding:0;list-style:none}.student-progress-attention-list li{display:flex;justify-content:space-between;gap:12px;padding:11px 13px;border-left:3px solid var(--warning);border-radius:var(--radius-sm);background:var(--surface-hover)}.student-progress-attention-list strong{display:block;color:var(--text-primary);font-size:.87rem}.student-progress-attention-list small{color:var(--text-muted)}@media(max-width:900px){.student-progress-header{display:block}.student-progress-filter{margin-top:16px;max-width:420px}.student-progress-primary{grid-template-columns:1fr}.student-progress-overview{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.student-progress-shell{padding:20px 14px}.student-progress-overview{gap:8px;grid-template-columns:1fr}.student-progress-metric{padding:12px}.student-progress-metric strong{font-size:1.08rem}.student-progress-hero-top{display:block}.student-progress-hero-status{margin-top:10px}.student-progress-hero-grid{grid-template-columns:1fr}.student-progress-section{padding:15px}.student-progress-section-header{display:block}.student-progress-section-date{display:block;margin-top:5px}.student-progress-row{display:block}.student-progress-actions{justify-content:flex-start;margin-top:8px}}
