</head>
<body class="body ds-bg-primary student-progress-page" style="margin-top:65px">
<div id="app"><div id="body-overlay" onclick="document.getElementById('aside-menu').classList.toggle('active');document.getElementById('body-overlay').classList.toggle('active');"></div><?php include 'layouts/user/aside.php'; ?><main class="font-2">
    <div class="student-analytics-navigation border-lg-top"><div class="container px-2"><nav class="navbar navbar-expand-lg navbar-light ds-surface-muted"><div class="container-fluid p-0"><button class="navbar-toggler d-lg-none" type="button" data-bs-toggle="collapse" data-bs-target="#navbarSupportedContent" aria-controls="navbarSupportedContent" aria-expanded="false" aria-label="Toggle navigation"><span class="fas fa-bars"></span></button><?php include 'layouts/user/main-nav.php'; ?></div></nav></div></div>
    <section class="student-progress-shell"><header class="student-progress-header"><div><p class="student-progress-eyebrow"><span class="fas fa-chart-line" aria-hidden="true"></span> Learning progress</p><h1>My Progress</h1><p>See what you attended, what you opened, and what needs your attention.</p></div><?php if ($courses): ?><form method="get" action="<?= $escape($base . '/user/analytics') ?>" class="student-progress-filter"><label for="student-progress-course">Course</label><select id="student-progress-course" name="course" class="form-select" onchange="this.form.submit()"><?php foreach ($courses as $course): ?><option value="<?= $escape($course['course_id']) ?>" <?= (string) $course['course_id'] === $selectedCourseId ? 'selected' : '' ?>><?= $escape($course['course_title']) ?></option><?php endforeach ?></select><label for="student-progress-period">Reporting period</label><select id="student-progress-period" name="period" class="form-select" onchange="this.form.submit()"><?php foreach ($periodOptions as $key => $label): ?><option value="<?= $escape($key) ?>" <?= $period && $period['key'] === $key ? 'selected' : '' ?>><?= $escape($label) ?></option><?php endforeach ?></select></form><?php endif; ?></header>
    <?php if (!$selectedCourse): ?><div class="student-progress-empty"><h2>No enrolled course yet</h2><p>Enroll in a course to see your learning progress.</p><a class="btn btn-primary" href="<?= $escape($base . '/user/courses') ?>">Browse courses</a></div>
    <?php elseif ($error): ?><div class="alert alert-danger" role="alert"><?= $escape($error) ?></div>
    <?php elseif ($summary): ?>
	      <p class="student-progress-period"><strong><?= $escape($selectedCourse['course_title']) ?></strong> · <?= $escape($period['label']) ?> · <?= $escape($period['start']) ?> to <?= $escape($period['end']) ?></p>
	      <?php $journey = $summary['learning_journey'] ?? []; $journeyPercent = $journey['percentage'] ?? null; $journeyTotal = (int) ($journey['total'] ?? 0); $journeyCompleted = (int) ($journey['completed'] ?? 0); ?>
	      <section class="student-progress-primary" aria-label="Overall progress">
	        <article class="student-progress-hero-card">
	          <div class="student-progress-hero-top"><div><h2>Learning Journey</h2><strong class="student-progress-hero-percent"><?= $escape($progressLabel($journeyPercent)) ?></strong></div><span class="student-progress-hero-status"><?= $journeyTotal > 0 && $journeyCompleted === $journeyTotal ? 'Complete' : ($journeyTotal > 0 ? 'Keep Going' : 'Progress will appear here') ?></span></div>
	          <div class="student-progress-hero-grid"><div><span>Course items complete</span><strong><?= $journeyCompleted ?> / <?= $journeyTotal ?></strong></div><div><span>Live attendance</span><strong><?= (int) $summary['counts']['live_attended'] ?> / <?= (int) $summary['counts']['live_total'] ?></strong></div><div><span>Homework submitted</span><strong><?= (int) $summary['counts']['homework_submitted'] ?> / <?= (int) $summary['counts']['homework_total'] ?></strong></div></div>
	        </article>
	        <aside class="student-progress-journey" aria-label="Progress journey">
	          <h2>Course timeline</h2>
	          <?php foreach (array_slice($journey['sections'] ?? [], 0, 3) as $journeySection): ?><div class="student-progress-journey-step"><h3><?= $escape($journeySection['title']) ?></h3><p><?= count(array_filter($journeySection['items'] ?? [], static fn($item) => !empty($item['is_completed']))) ?> of <?= count($journeySection['items'] ?? []) ?> course items complete</p><div class="student-progress-journey-facts"><?php foreach (array_slice($journeySection['items'] ?? [], 0, 3) as $journeyItem): ?><span><?= $escape($journeyItem['item_title']) ?> <b><?= !empty($journeyItem['is_completed']) ? '✓' : '○' ?></b></span><?php endforeach; ?></div></div><?php endforeach; ?>
	        </aside>
	      </section>
	      <section class="student-progress-overview" aria-label="Progress overview"><article class="student-progress-metric"><span>Live attendance</span><strong><?= (int) $summary['counts']['live_attended'] ?> / <?= (int) $summary['counts']['live_total'] ?></strong></article><article class="student-progress-metric"><span>Homework submitted</span><strong><?= (int) $summary['counts']['homework_submitted'] ?> / <?= (int) $summary['counts']['homework_total'] ?></strong></article><article class="student-progress-metric"><span>Recording opened</span><strong><?= (int) $summary['counts']['recording_opened'] + (int) $summary['counts']['recording_completed'] ?></strong></article><article class="student-progress-metric"><span>Average grade</span><strong><?= $summary['counts']['average_grade'] === null ? 'Not Available' : $escape($summary['counts']['average_grade']) . ' / 10' ?></strong></article></section>
      <?php if (!$summary['sections']): ?><div class="student-progress-empty">No published sections have activity in this period.</div><?php endif; ?>
      <?php foreach ($summary['sections'] as $section): ?><article class="student-progress-section"><header class="student-progress-section-header"><div><h2><?= $escape($section['title']) ?><?= !empty($section['is_workshop']) ? ' <small>(Workshop)</small>' : '' ?></h2></div><span class="student-progress-section-date"><?= $escape($section['date']) ?></span></header>
        <?php if ($section['attendance']): ?><div class="student-progress-row"><span class="student-progress-row-label"><span class="fas fa-user-check" aria-hidden="true"></span> Live Session</span><span class="student-progress-status <?= $escape($statusClass($section['attendance']['key'])) ?>"><span aria-hidden="true">●</span><?= $escape($section['attendance']['label']) ?></span></div><?php endif; ?>
        <?php foreach ($section['recordings'] as $recording): ?><div class="student-progress-row"><span class="student-progress-row-label"><span class="fas fa-play-circle" aria-hidden="true"></span><?= $escape($recording['title'] ?: 'Recording') ?></span><span class="student-progress-actions"><span class="student-progress-status <?= $escape($statusClass($recording['status']['key'])) ?>"><span aria-hidden="true">●</span><?= $escape($recording['status']['label']) ?></span><?php if (in_array($recording['status']['key'], ['opened', 'not_viewed'], true) && $recording['item_id'] !== ''): ?><a class="student-progress-action" href="<?= $escape($resourceUrl($selectedCourseId, $recording['item_id'])) ?>">Continue Recording</a><?php endif; ?></span></div><?php endforeach; ?>
        <?php foreach ($section['homework'] as $homework): ?><div class="student-progress-row"><span class="student-progress-row-label"><span class="fas fa-clipboard-check" aria-hidden="true"></span><?= $escape($homework['title'] ?: 'Homework') ?></span><span class="student-progress-actions"><span class="student-progress-status <?= $escape($statusClass($homework['status']['key'])) ?>"><span aria-hidden="true">●</span><?= $escape($homework['status']['label']) ?></span><?php if ($homework['item_id'] !== ''): ?><a class="student-progress-action" href="<?= $escape($resourceUrl($selectedCourseId, $homework['item_id'])) ?>">Open Homework</a><?php endif; ?></span></div><?php endforeach; ?>
        <?php if (!$section['attendance'] && !$section['recordings'] && !$section['homework']): ?><p class="student-progress-empty">No recorded activity for this section.</p><?php endif; ?></article><?php endforeach; ?>
      <?php if ($summary['weak_points']): ?><section class="student-progress-attention"><h2>Needs attention</h2><ul class="student-progress-attention-list"><?php foreach ($summary['weak_points'] as $point): ?><li><div><strong><?= $escape($point['section_title']) ?></strong><small><?= $escape(implode(' · ', $point['reasons'])) ?></small></div><?php foreach ($point['actions'] as $action): ?><?php if ($action['type'] === 'recording'): ?><a class="student-progress-action" href="<?= $escape($resourceUrl($selectedCourseId, $action['item_id'])) ?>">Continue Recording</a><?php elseif ($action['type'] === 'homework'): ?><a class="student-progress-action" href="<?= $escape($resourceUrl($selectedCourseId, $action['item_id'])) ?>">Open Homework</a><?php endif; ?><?php endforeach; ?></li><?php endforeach; ?></ul></section><?php endif; ?>
    <?php endif; ?></section>
</main><?php include 'layouts/user/footer.php'; ?></div>
